with target as(select * from public.works where id=any(array[1527,1839,5019,1860,4962,4987,5053,5884,5953,6072]::bigint[]) or open_library_id=any(array['OL88214W','OL361665W','OL18725336W','OL193961W','OL79341W','OL22272750W','OL7982341W','OL22903W','OL17139354W','OL19742698W']::text[]) or regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['arspoetica','pericles','demondvolvogels','pajarosenlaboca','dagboek16601669','diary','laatstekans','darkestfear','paradais','thereseraquin','krachtmeting','thegoldcoast','zevenlegehuizen','sietecasasvacias','deordevandedag','lordredujour']::text[]) or id in(select work_id from public.catalog_work_title_aliases where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['arspoetica','pericles','demondvolvogels','pajarosenlaboca','dagboek16601669','diary','laatstekans','darkestfear','paradais','thereseraquin','krachtmeting','thegoldcoast','zevenlegehuizen','sietecasasvacias','deordevandedag','lordredujour']::text[]))),a as(select * from public.authors where id in(select author_id from target) or open_library_id=any(array['OL20088A','OL564289A','OL9388A','OL1538447A','OL2111876A','OL39821A','OL7400439A','OL32772A','OL25714A','OL1450411A']::text[]) or regexp_replace(lower(normalize(name,NFD)),'[^a-z0-9]','','g')=any(array['horace','quintushoratiusflaccus','qhoratiusflaccus','horatius','florianomartins','williamshakespeare','thebardofavon','cletusshakespeare','guillermoshakespeare','samantaschweblin','schweblin','samuelpepys','pepyssamuel16331703','pepyssamuel','harlancoben','cobenharlan','fernandamelchor','emilezola','emileedouardcharlesantoinezola','nelsondemille','bradmatthewspseud','jackcannonpseud','kurtladnerpseud','ericvuillard','evuillard']::text[])),e as(select * from public.editions where work_id in(select id from target) or open_library_edition_id=any(array['OL24329910M','OL24405551M','OL58498671M','OL17518560M','OL45636160M','OL58465114M','OL25208842M','OL47808986M','OL58499907M','OL45297594M']::text[]) or regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789025315634','9789035104556','9789058315595','9789022838860','9789022569894','9789028451445','9789027421388','9789044304350','9789493169241','9789029092708']::text[])) select jsonb_build_object('project','qvplwejffhjvxaypmjut','checked_at',clock_timestamp(),'works',coalesce((select jsonb_agg(to_jsonb(t) order by id) from target t),'[]'),'authors',coalesce((select jsonb_agg(to_jsonb(t) order by id) from a t),'[]'),'author_corpora',coalesce((select jsonb_agg(to_jsonb(t) order by id) from public.works t where author_id in(select id from a)),'[]'),'editions',coalesce((select jsonb_agg(to_jsonb(t) order by id) from e t),'[]'),'metadata',coalesce((select jsonb_agg(to_jsonb(t) order by edition_id) from public.catalog_edition_metadata t where edition_id in(select id from e)),'[]'),'descriptions',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,language) from public.catalog_work_descriptions t where work_id in(select id from target)),'[]'),'aliases',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,title) from public.catalog_work_title_aliases t where work_id in(select id from target)),'[]')) as snapshot;
